Ext.define('BNK.view.common.FindUserPopupMViewController', {
    extend: 'BaseViewController',
    alias: 'controller.FindUserPopupMViewController',

    config: {
        viewId: 'FindUserPopupM'
    },

    tab2ButtonSetter: function(visibleParam) {
        var me = this;
        var refs = me.getReferences();
        refs.addBtn.setVisibility(visibleParam);
        refs.modifyBtn.setVisibility(!visibleParam);
        refs.delBtn.setVisibility(!visibleParam);

        if(visibleParam){
            refs.dpnm.setValue('');
            refs.empePsitNm.setValue('');
            refs.empeNo.setValue('');
            refs.empeNm.setValue('');
            refs.id.setValue('');
        }

    },

    onSelect: function(pageReset) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            store = me.getStore('EMPINFOStore'),
            command = vm.get('command'),
            page = arguments[0] || 1; // 페이지 초기화


        //r empeNm = refs.searchName.getValue();
        var hrHrpmDeptId = refs.searchDept.getValue();
        store.getProxy().extraParams = {
            command : command,
            hrHrpmDeptId  : hrHrpmDeptId == 999 ? '': hrHrpmDeptId,
            wkingDvcdList : [Constants.wkingDvcd.WORK_NORMAL,
                             Constants.wkingDvcd.WORK_CONCURRENT,
                             Constants.wkingDvcd.WORK_DISPATCH]
        };

        if(pageReset){
             store.getProxy().extraParams.page = 1;
             var toolbar = refs.gridUp.getPlugins()[0];
             toolbar.setCurrentPage(1);
        }

        store.removeAll();
        store.loadPage(1);

    },

    checkDuplicate: function(data) {
        var me = this,
        	vm = me.getViewModel(),
        	refs = me.getReferences(),
        	store = me.getStore('SelectEmpStore');

        var checkData = store.getData();
        // store.getData().items[0].data

        var result = 0;
        for(var i = 0 ; i < checkData.length ; i ++){
            var tempData = checkData.items[i].data;
            var checkVal = tempData.empeNo + tempData.empeNm;
            if(checkVal == data){
                result ++;
            }
        }
        if(result !=0){
            Ext.Msg.alert('확인', '연락처와 성명은 중복이 될 수 없습니다');
        }
        return  result >0 ? true : false;

    },

    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            gridDown = refs.gridDown;

        me.GET_CODELIST({stcd : "01" , codeDvcd : 'DEPTLV'})
        .then(function(records) {
            var store = me.getViewModel().get('DeptStore');
            store.add({text : "- 전  체 -", value : 999});
            store.add(records.data);
            refs.searchDept.setValue(SecurityUtils.getPrincipal().hrHrpmDeptId);
            me.onSelect(false);

        });
        if(component.extenalEmpHidden){
            refs.tab.remove(refs.extenalEmp);
        }
        // 업무추진비 아닐 때, 외부직원 탭 막기 NTE011
        var accItemCd = component.initialConfig.accItemCd;
        if(accItemCd === '09'){ // 업무추진비
            refs.extenalEmp.setDisabled(false);
            refs.addBtn.setDisabled(false);
            refs.modifyBtn.setDisabled(false);
            refs.delBtn.setDisabled(false);
            refs.resetBtn.setDisabled(false);

            refs.dpnm.setDisabled(false);
            refs.empePsitNm.setDisabled(false);
            refs.empeNo.setDisabled(false);
            refs.empeNm.setDisabled(false);

        } else {
            refs.extenalEmp.setDisabled(true);
            refs.addBtn.setDisabled(true);
            refs.modifyBtn.setDisabled(true);
            refs.delBtn.setDisabled(false);
            refs.resetBtn.setDisabled(true);

            refs.dpnm.setDisabled(true);
            refs.empePsitNm.setDisabled(true);
            refs.empeNo.setDisabled(true);
            refs.empeNm.setDisabled(true);
        }

        var gridData = component.initialConfig.gridData;
        for(var i in gridData){
            this.getStore('SelectEmpStore').add(gridData[i]);
        }

    },

    onMycombobox1Select: function(combobox, newValue, oldValue, eOpts) {
        this.onSelect();
    },

    /* Grid1 -> Grid2 */
    onGridEmpInfoClick: function(dataview, selected, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.gridUp,
            grid2 = refs.gridDown,
            gridUp = refs.gridUp,
            gridDown = refs.gridDown,
            grid2_len = gridDown.innerItems.length,
            selectedEmp = selected[0];

        var grid2Store = this.getStore('SelectEmpStore').data.items;
        for(var i in grid2Store){
            if(grid2Store[i].data.hrHrpmEmpId === selectedEmp.data.hrHrpmEmpId){
                return false;
            }
        }

        selectedEmp.set("stfDvcd",'01'); // 내부직원 01, 외부직원 02 구분 // TODO : 하드코딩 수정할 수 있으면 수정해 주세요.
        selectedEmp.set("stfDvcdNm",'내부직원'); // 내부직원 01, 외부직원 02 구분 // TODO : 하드코딩 수정할 수 있으면 수정해 주세요.
        gridDown.getStore().add(selectedEmp);

    },

    onAddBtnTap: function(button, e, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var gridDown = refs.gridDown;

        var empePsitNm = refs.empePsitNm.getValue();
        var dpnm = refs.dpnm.getValue();
        var empeNo = refs.empeNo.getValue();
        var empeNm = refs.empeNm.getValue();

        if(empePsitNm == "" || dpnm == "" || empeNo == "" || empeNm == ""){
            Ext.Msg.alert('확인', '모든 항목의 값을 입력 하여 주세요');
            return;
        }
        var checkDp = me.checkDuplicate(empeNo + empeNm);
        if(me.checkDuplicate(empeNo + empeNm)){
            return;
        };

        var obj = new Object();
        obj.empePsitNm = empePsitNm;
        obj.dpnm = dpnm;
        obj.empeNo = empeNo;
        obj.empeNm = empeNm;
        obj.stfDvcd = "02";
        obj.stfDvcdNm = "외부직원";

        var temp =gridDown.getStore().insert(0, obj);
        refs.id.setValue(temp[0].id);

        me.tab2ButtonSetter(false);
        //Ext.toast("입력 하였습니다");
    },

    onAlterBtnTap: function(button, e, eOpts) {
        var me = this;
        var refs = me.getReferences();

        var empePsitNm = refs.empePsitNm.getValue();
        var dpnm = refs.dpnm.getValue();
        var empeNo = refs.empeNo.getValue();
        var empeNm = refs.empeNm.getValue();

        var obj = new Object();
        obj.empePsitNm = empePsitNm;
        obj.dpnm = dpnm;
        obj.empeNo = empeNo;
        obj.empeNm = empeNm;
        obj.id = refs.id.getValue();

        if(empePsitNm == "" || dpnm == "" || empeNo == "" || empeNm == ""){
            Ext.Msg.alert('확인', '모든 항목의 값을 입력 하여 주세요');
            return;
        }

        if(this.checkDuplicate(empeNo + empeNm))return;


        var gridInfo = refs.gridDown.getStore().getById(obj.id);
        gridInfo.set("empePsitNm", obj.empePsitNm);
        gridInfo.set("dpnm", obj.dpnm);
        gridInfo.set("empeNo", obj.empeNo);
        gridInfo.set("empeNm", obj.empeNm);
        gridInfo.set("id", obj.id);
        //Ext.toast("수정 하였습니다");
    },

    /* 외부사용자 삭제 */
    onExtEmpDel: function(button, e, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var store = refs.gridDown.getStore();
        var items = store.getData().items;
        var deleteId = refs.id.getValue();


        for(var i in items){
            if(deleteId == items[i].id){
                store.removeAt(i);
                me.tab2ButtonSetter(true);
                break;
            }
        }
        //Ext.toast("삭제 하였습니다");
    },

    onButtonResetTap: function(button, e, eOpts) {
        this.tab2ButtonSetter(true);
    },

    onTabpanelActiveItemChange: function(sender, value, oldValue, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var index = sender.getActiveItemIndex();
        me.tab2ButtonSetter(true);
    },

    /* 아래 그리드 Cell 클릭 이벤트 */
    onGridSelectSelected: function(dataview, selected, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var grid = refs.gridDown;

        var stfDvcd = selected[0].get("stfDvcd");
        if(stfDvcd == '01'){
            grid.getStore().remove(selected[0]);
            //Ext.toast("삭제 하였습니다");
        }else{
            refs.tab.setActiveItemIndex(1);
            refs.id.setValue(selected[0].data.id);
            refs.empePsitNm.setValue(selected[0].data.empePsitNm);
            refs.dpnm.setValue(selected[0].data.dpnm);
            refs.empeNo.setValue(selected[0].data.empeNo);
            refs.empeNm.setValue(selected[0].data.empeNm);
            me.tab2ButtonSetter(false);
        }

    },

    onBtnCloseTap: function(button, e, eOpts) {
        this.getView().close();
    },

    onBtnSearchTap: function(button, e, eOpts) {
        var me = this;
        var refs  = me.getReferences();
        var storeDown = refs.gridDown.getStore();

        me.getView().fireEvent('selected', storeDown.data);
        me.getView().close();
    }

});